// The capture the program writes: classic pcap, each record Ethernet, IPv4 and UDP around a payload
class Capture {
  public:
    explicit Capture(const std::string& path) : out_(path, std::ios::binary) {
        word(0xa1b2c3d4u); half(2); half(4); word(0); word(0); word(65535); word(1);
    }

    void write(const std::vector<std::byte>& payload) {
        const auto udp = static_cast<std::uint16_t>(8 + payload.size());
        const auto ip = static_cast<std::uint16_t>(20 + udp);
        std::vector<std::uint8_t> frame(14 + ip, 0);

        // Ethernet: no addresses, carrying IPv4
        frame[12] = 0x08;

        // IPv4: no options, its length, UDP from 10.0.0.1 to 10.0.0.2
        frame[14] = 0x45;
        frame[16] = static_cast<std::uint8_t>(ip >> 8);
        frame[17] = static_cast<std::uint8_t>(ip);
        frame[22] = 64;
        frame[23] = 17;
        frame[26] = 10;
        frame[29] = 1;
        frame[30] = 10;
        frame[33] = 2;

        // UDP: its ports and its length, then the payload
        frame[35] = 1;
        frame[37] = 2;
        frame[38] = static_cast<std::uint8_t>(udp >> 8);
        frame[39] = static_cast<std::uint8_t>(udp);
        for (std::size_t index = 0; index < payload.size(); ++index) {
            frame[42 + index] = static_cast<std::uint8_t>(payload[index]);
        }

        word(0);
        word(0);
        word(static_cast<std::uint32_t>(frame.size()));
        word(static_cast<std::uint32_t>(frame.size()));
        out_.write(reinterpret_cast<const char*>(frame.data()), static_cast<std::streamsize>(frame.size()));
    }

    bool good() const { return out_.good(); }

  private:
    void word(std::uint32_t value) { out_.write(reinterpret_cast<const char*>(&value), 4); }
    void half(std::uint16_t value) { out_.write(reinterpret_cast<const char*>(&value), 2); }

    std::ofstream out_;
};

